sysauto_script.script:
var DEADLINE_TABLE =
    'x_snc_campusmatch_campusmatch_deadline';

var CLAIM_TABLE =
    'x_snc_campusmatch_campusmatch_claim';

var ITEM_TABLE =
    'x_snc_campusmatch_campusmatch_item';

var now = new GlideDateTime();


/* =====================================================
   PROCESS EXPIRED COLLECTION DEADLINES
===================================================== */

var deadline = new GlideRecord(DEADLINE_TABLE);

deadline.addQuery('status', 'active');
deadline.addQuery('deadline_type', 'collection');
deadline.addQuery('due_date_time', '<=', now);
deadline.addQuery('expiry_processed', false);
deadline.query();

while (deadline.next()) {

    var claim = new GlideRecord(CLAIM_TABLE);

    if (!claim.get(deadline.getValue('claim'))) {
        deadline.setValue('expiry_processed', true);
        deadline.update();
        continue;
    }


    /* Already collected → simply complete deadline */

    if (claim.getValue('handover_completed') == 'true') {

        deadline.setValue('status', 'completed');
        deadline.setValue('expiry_processed', true);
        deadline.update();

        continue;
    }


    /* ---------------------------------------------
       COLLECTION EXPIRED
    --------------------------------------------- */

    claim.setValue(
        'claim_status',
        'collection_expired'
    );

    // Kill old QR/token
    claim.setValue(
        'collection_toke0',
        ''
    );

    claim.update();


    /* ---------------------------------------------
       ITEM RETURNS TO UNCLAIMED
    --------------------------------------------- */

    var item = new GlideRecord(ITEM_TABLE);

    if (item.get(deadline.getValue('item'))) {

        item.setValue(
            'status',
            'unclaimed'
        );

        item.update();
    }


    /* ---------------------------------------------
       CLOSE COLLECTION DEADLINE
    --------------------------------------------- */

    deadline.setValue(
        'status',
        'expired'
    );

    deadline.setValue(
        'expiry_processed',
        true
    );

    deadline.update();


    /* ---------------------------------------------
       CREATE RETENTION DEADLINE
       Prevent duplicates
    --------------------------------------------- */

    var existingRetention =
        new GlideRecord(DEADLINE_TABLE);

    existingRetention.addQuery(
        'item',
        deadline.getValue('item')
    );

    existingRetention.addQuery(
        'deadline_type',
        'retention'
    );

    existingRetention.addQuery(
        'status',
        'active'
    );

    existingRetention.setLimit(1);
    existingRetention.query();

    if (!existingRetention.hasNext()) {

        var retentionStart =
            new GlideDateTime();

        var retentionDue =
            new GlideDateTime(retentionStart);

        // Demo/final configuration for now
        retentionDue.addDaysUTC(30);


        var retention =
            new GlideRecord(DEADLINE_TABLE);

        retention.initialize();

        retention.setValue(
            'deadline_type',
            'retention'
        );

        retention.setValue(
            'item',
            deadline.getValue('item')
        );

        // NO claim/user:
        // retention is an ADMIN deadline

        retention.setValue(
            'start_date_time',
            retentionStart
        );

        retention.setValue(
            'due_date_time',
            retentionDue
        );

        retention.setValue(
            'status',
            'active'
        );

        retention.setValue(
            'reminder_sent',
            false
        );

        retention.setValue(
            'expiry_processed',
            false
        );

        retention.insert();
    }
}
